"""Short text notices for parents about missed days."""

from typing import Iterable, List
from rosterkit.models import Mark, Student
from datetime import date

def _absent_days(student: Student, marks: Iterable[Mark]) -> List[date]:
    marks = list(marks)
    if any(mark.student_id != student.student_id for mark in marks):
        raise ValueError("marks belong to a different student")
    days = sorted(mark.day for mark in marks if mark.status == "absent")
    if not days:
        raise ValueError("no absences to report")
    return days

# ---
def absence_notice(student: Student, marks: Iterable[Mark]) -> str:
    days = _absent_days(student, marks)
    dates = ", ".join(day.isoformat() for day in days)
    unit = "day" if len(days) == 1 else "days"
    return (
        f"{student.first_name} {student.last_name} missed {len(days)} {unit}: {dates}"
    )
